from pathlib import Path

root = Path(__file__).resolve().parent
manager = root / "app/src/main/java/com/threerdi/dfamstyle/BleMidiSyncManager.java"
s = manager.read_text()

old_fields = '''    private volatile long lastIncomingClockNs = 0L;\n    private volatile double avgClockIntervalNs = 0.0;\n    private volatile long syncRevision = 0L;'''
new_fields = '''    private volatile long lastIncomingClockNs = 0L;\n    private volatile double avgClockIntervalNs = 0.0;\n    private volatile long syncRevision = 0L;\n    private volatile long incomingClockCount = 0L;\n    private volatile int lastBleTimestampLow = -1;\n    private final double[] clockPeriodSamplesMs = new double[48];\n    private int clockPeriodSampleCount = 0;\n    private int clockPeriodSamplePos = 0;\n    private int lastPacketHash = 0;\n    private long lastPacketArrivalNs = 0L;'''
if old_fields not in s:
    raise RuntimeError("Could not find BLE MIDI timing fields")
s = s.replace(old_fields, new_fields, 1)

old_getter = '''    public long getSyncRevision() { return syncRevision; }\n    public boolean hasIncomingClock() { return lastIncomingClockNs != 0L && (System.nanoTime() - lastIncomingClockNs) < 2_000_000_000L; }'''
new_getter = '''    public long getSyncRevision() { return syncRevision; }\n    public long getIncomingClockCount() { return incomingClockCount; }\n    public boolean hasIncomingClock() { return lastIncomingClockNs != 0L && (System.nanoTime() - lastIncomingClockNs) < 2_000_000_000L; }'''
if old_getter not in s:
    raise RuntimeError("Could not find BLE MIDI getter block")
s = s.replace(old_getter, new_getter, 1)

# Reset robust clock state whenever a new slave scan starts.
old_scan_reset = '''        incomingBpm = 0f;\n        lastIncomingClockNs = 0L;\n        avgClockIntervalNs = 0.0;\n        synchronized (this) { scannedDevices.clear(); }'''
new_scan_reset = '''        incomingBpm = 0f;\n        lastIncomingClockNs = 0L;\n        avgClockIntervalNs = 0.0;\n        incomingClockCount = 0L;\n        lastBleTimestampLow = -1;\n        clockPeriodSampleCount = 0;\n        clockPeriodSamplePos = 0;\n        lastPacketHash = 0;\n        lastPacketArrivalNs = 0L;\n        synchronized (this) { scannedDevices.clear(); }'''
if old_scan_reset not in s:
    raise RuntimeError("Could not find slave reset block")
s = s.replace(old_scan_reset, new_scan_reset, 1)

old_disconnect_reset = '''        lastIncomingClockNs = 0L;\n        avgClockIntervalNs = 0.0;\n        syncRevision++;'''
new_disconnect_reset = '''        lastIncomingClockNs = 0L;\n        avgClockIntervalNs = 0.0;\n        incomingClockCount = 0L;\n        lastBleTimestampLow = -1;\n        clockPeriodSampleCount = 0;\n        clockPeriodSamplePos = 0;\n        syncRevision++;'''
if old_disconnect_reset not in s:
    raise RuntimeError("Could not find disconnect reset block")
s = s.replace(old_disconnect_reset, new_disconnect_reset, 1)

old_clock_thread = '''    private void startClockThread() {\n        if (clockThreadActive.getAndSet(true)) return;\n        clockThread = new Thread(() -> {\n            long next = System.nanoTime();\n            while (clockThreadActive.get()) {\n                if (mode != MODE_MASTER || !masterRunning) {\n                    next = System.nanoTime();\n                    LockSupport.parkNanos(5_000_000L);\n                    continue;\n                }\n                long period = (long) (60_000_000_000.0 / (Math.max(20f, masterBpm) * 24.0));\n                next += period;\n                sendMidiRealtime((byte) 0xF8);\n                long wait = next - System.nanoTime();\n                if (wait > 0) LockSupport.parkNanos(wait);\n                else next = System.nanoTime();\n            }\n        }, "BLE-MIDI-Clock");\n        clockThread.setDaemon(true);\n        clockThread.start();\n    }'''
new_clock_thread = '''    private void startClockThread() {\n        if (clockThreadActive.getAndSet(true)) return;\n        clockThread = new Thread(() -> {\n            long next = System.nanoTime();\n            int[] bundleTimestamps = new int[9];\n            int bundleCount = 0;\n            while (clockThreadActive.get()) {\n                if (mode != MODE_MASTER || !masterRunning) {\n                    bundleCount = 0;\n                    next = System.nanoTime();\n                    LockSupport.parkNanos(5_000_000L);\n                    continue;\n                }\n\n                float bpm = Math.max(20f, Math.min(300f, masterBpm));\n                long period = (long) (60_000_000_000.0 / (bpm * 24.0));\n                int targetBundle = Math.max(1, Math.min(9, (int) Math.ceil(bpm / 50.0)));\n\n                bundleTimestamps[bundleCount++] = (int) (System.currentTimeMillis() & 0x1FFF);\n                if (bundleCount >= targetBundle) {\n                    sendClockBundle(bundleTimestamps, bundleCount);\n                    bundleCount = 0;\n                }\n\n                next += period;\n                long wait = next - System.nanoTime();\n                if (wait > 0) LockSupport.parkNanos(wait);\n                else next = System.nanoTime();\n            }\n        }, "BLE-MIDI-Clock");\n        clockThread.setDaemon(true);\n        clockThread.start();\n    }\n\n    @SuppressLint("MissingPermission")\n    private void sendClockBundle(int[] timestamps, int count) {\n        BluetoothGattServer server = gattServer;\n        BluetoothGattCharacteristic characteristic = serverCharacteristic;\n        if (server == null || characteristic == null || subscribers.isEmpty() || count <= 0) return;\n\n        count = Math.min(9, count);\n        byte[] packet = new byte[1 + count * 2];\n        int first = timestamps[0] & 0x1FFF;\n        packet[0] = (byte) (0x80 | ((first >> 7) & 0x3F));\n        for (int i = 0; i < count; i++) {\n            int ts = timestamps[i] & 0x1FFF;\n            packet[1 + i * 2] = (byte) (0x80 | (ts & 0x7F));\n            packet[2 + i * 2] = (byte) 0xF8;\n        }\n\n        for (BluetoothDevice device : subscribers) {\n            try {\n                if (Build.VERSION.SDK_INT >= 33) {\n                    server.notifyCharacteristicChanged(device, characteristic, false, packet);\n                } else {\n                    characteristic.setValue(packet);\n                    server.notifyCharacteristicChanged(device, characteristic, false);\n                }\n            } catch (Exception ignored) { }\n        }\n    }'''
if old_clock_thread not in s:
    raise RuntimeError("Could not find old BLE MIDI clock thread")
s = s.replace(old_clock_thread, new_clock_thread, 1)

old_parser = '''    private void parseBleMidi(byte[] value) {\n        if (value == null) return;\n        for (byte raw : value) {\n            int b = raw & 0xFF;\n            if (b == 0xF8) handleClock();\n            else if (b == 0xFA || b == 0xFB) {\n                incomingRunning = true;\n                syncRevision++;\n                notifySync();\n            } else if (b == 0xFC) {\n                incomingRunning = false;\n                syncRevision++;\n                notifySync();\n            }\n        }\n    }\n\n    private void handleClock() {\n        long now = System.nanoTime();\n        long last = lastIncomingClockNs;\n        lastIncomingClockNs = now;\n        if (last != 0L) {\n            long dt = now - last;\n            if (dt > 4_000_000L && dt < 150_000_000L) {\n                if (avgClockIntervalNs == 0.0) avgClockIntervalNs = dt;\n                else avgClockIntervalNs = avgClockIntervalNs * 0.90 + dt * 0.10;\n                float bpm = (float) (60_000_000_000.0 / (avgClockIntervalNs * 24.0));\n                if (bpm >= 20f && bpm <= 300f) incomingBpm = bpm;\n            }\n        }\n        syncRevision++;\n        if ((syncRevision & 3L) == 0L) notifySync();\n    }'''
new_parser = '''    private synchronized void parseBleMidi(byte[] value) {\n        if (value == null || value.length == 0) return;\n\n        // Android 13+ exposes a second onCharacteristicChanged callback. Some phone\n        // stacks can surface the same notification through both callbacks, so drop\n        // byte-identical duplicates that arrive essentially simultaneously.\n        long packetNowNs = System.nanoTime();\n        int packetHash = java.util.Arrays.hashCode(value);\n        if (packetHash == lastPacketHash && packetNowNs - lastPacketArrivalNs < 3_000_000L) return;\n        lastPacketHash = packetHash;\n        lastPacketArrivalNs = packetNowNs;\n\n        boolean parsedTimestampedEvent = false;\n        int fallbackClockCount = 0;\n        int i = 1; // byte 0 is the BLE-MIDI timestamp-high header\n        while (i < value.length) {\n            int tsByte = value[i] & 0xFF;\n            if ((tsByte & 0x80) != 0 && i + 1 < value.length) {\n                int message = value[i + 1] & 0xFF;\n                if (message == 0xF8 || message == 0xFA || message == 0xFB || message == 0xFC) {\n                    parsedTimestampedEvent = true;\n                    int timestampLow = tsByte & 0x7F;\n                    if (message == 0xF8) handleClockTimestamp(timestampLow);\n                    else handleTransport(message);\n                    i += 2;\n                    continue;\n                }\n            }\n\n            int b = value[i] & 0xFF;\n            if (b == 0xF8) fallbackClockCount++;\n            else if (b == 0xFA || b == 0xFB || b == 0xFC) handleTransport(b);\n            i++;\n        }\n\n        // Fallback for non-standard/simple senders without usable BLE timestamps.\n        if (!parsedTimestampedEvent && fallbackClockCount > 0) {\n            long previous = lastIncomingClockNs;\n            lastIncomingClockNs = packetNowNs;\n            incomingClockCount += fallbackClockCount;\n            if (previous != 0L) {\n                double candidateMs = (packetNowNs - previous) / 1_000_000.0 / fallbackClockCount;\n                addClockPeriodSample(candidateMs);\n            }\n            syncRevision += fallbackClockCount;\n            notifySync();\n        }\n    }\n\n    private void handleTransport(int message) {\n        if (message == 0xFA || message == 0xFB) {\n            incomingRunning = true;\n            syncRevision++;\n            notifySync();\n        } else if (message == 0xFC) {\n            incomingRunning = false;\n            syncRevision++;\n            notifySync();\n        }\n    }\n\n    private void handleClockTimestamp(int timestampLow) {\n        lastIncomingClockNs = System.nanoTime();\n        incomingClockCount++;\n\n        int previous = lastBleTimestampLow;\n        lastBleTimestampLow = timestampLow & 0x7F;\n        if (previous >= 0) {\n            int deltaMs = ((timestampLow & 0x7F) - previous + 128) & 0x7F;\n            if (deltaMs > 0) addClockPeriodSample(deltaMs);\n        }\n\n        syncRevision++;\n        if ((incomingClockCount % 6L) == 0L) notifySync();\n    }\n\n    private void addClockPeriodSample(double candidateMs) {\n        if (candidateMs < 4.0 || candidateMs > 127.0) return;\n\n        // If a complete BLE notification was lost, the timestamp gap can be an\n        // integer multiple of the real MIDI-clock period. Fold it back toward the\n        // established period before adding it to the estimator.\n        if (avgClockIntervalNs > 0.0) {\n            double expectedMs = avgClockIntervalNs / 1_000_000.0;\n            if (candidateMs > expectedMs * 1.55) {\n                int multiple = (int) Math.round(candidateMs / expectedMs);\n                if (multiple >= 2 && multiple <= 9) {\n                    double folded = candidateMs / multiple;\n                    if (folded > expectedMs * 0.65 && folded < expectedMs * 1.35) candidateMs = folded;\n                }\n            }\n            if (candidateMs < expectedMs * 0.55 || candidateMs > expectedMs * 1.65) return;\n        }\n\n        clockPeriodSamplesMs[clockPeriodSamplePos] = candidateMs;\n        clockPeriodSamplePos = (clockPeriodSamplePos + 1) % clockPeriodSamplesMs.length;\n        if (clockPeriodSampleCount < clockPeriodSamplesMs.length) clockPeriodSampleCount++;\n\n        double[] copy = java.util.Arrays.copyOf(clockPeriodSamplesMs, clockPeriodSampleCount);\n        java.util.Arrays.sort(copy);\n        double median = copy[copy.length / 2];\n        double sum = 0.0;\n        int accepted = 0;\n        for (double sample : copy) {\n            if (sample >= median * 0.72 && sample <= median * 1.28) {\n                sum += sample;\n                accepted++;\n            }\n        }\n        if (accepted == 0) return;\n\n        double robustMs = sum / accepted;\n        double robustNs = robustMs * 1_000_000.0;\n        if (avgClockIntervalNs == 0.0) avgClockIntervalNs = robustNs;\n        else avgClockIntervalNs = avgClockIntervalNs * 0.80 + robustNs * 0.20;\n\n        float bpm = (float) (60_000_000_000.0 / (avgClockIntervalNs * 24.0));\n        if (bpm >= 20f && bpm <= 300f) incomingBpm = bpm;\n    }'''
if old_parser not in s:
    raise RuntimeError("Could not find old BLE MIDI parser")
s = s.replace(old_parser, new_parser, 1)

manager.write_text(s)
print("Applied v2.6 robust BLE MIDI timestamp/clock patch")
